    if (start > end) {
        return true;
    }

    int mid = (start + end) / 2;

    if (arr[mid] <= arr[start] || (arr[mid] > arr[end])) {
        return false;
    }

    return isValidBST(arr, start, mid - 1) && isValidBST(arr, mid + 1, end);
