    return a.w < b.w;
}

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    vector<Edge> edges(m);
    for (int i = 0; i < m; i++) {
        cin >> edges[i].u >> edges[i].v >> edges[i].w;
    }

    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    pq.push({INF, 1});
    vector<int> dist(n + 1, INF);
    dist[1] = 0;

    while (!pq.empty()) {
        auto [dist_val, u] = pq.top();
        pq.pop();

        if (dist_val > dist[u]) continue;

        for (int i = 1; i <= n; i++) {
            if (dist[i] > dist_val + edges[u].w) {
                dist[i] = dist_val + edges[u].w;
                pq.push({dist[i], i});
            }
        }
    }

    vector<int> ans(k);
    for (int i = 1; i <= k; i++) {
        ans[i - 1] = dist[edges[i].u];
    }

    sort(ans.begin(), ans.end());

    for (int i = 1; i <= k; i++) {
        cout << ans[i - 1] << endl;
    }

    return 0;
}
