// Define the URL template
const urlTemplate = `https://avataaars.io/api/v1/avatar/${item.id}/`;

// Function to generate the URL
function generateUrl(itemId) {
  return urlTemplate.replace('${item.id}', itemId);
}

// Function to update the avatar
function updateAvatar(itemId, newOption) {
  // Get the current URL
  const currentUrl = generateUrl(itemId);

  // Update the URL
  currentUrl = currentUrl.replace('${item.id}', itemId);

  // Store the updated URL in local storage
  localStorage.setItem('avatarUrl', currentUrl);

  // Update the item-group elements
  updateItemGroupElements();
}

// Function to update the item-group elements
function updateItemGroupElements() {
  // Get the current URL from local storage
  const avatarUrl = localStorage.getItem('avatarUrl');

  // If the URL is not set, return
  if (!avatarUrl) {
    return;
  }

  // Split the URL into its components
  const [base, path] = avatarUrl.split('/');

  // Create the item-group element
  const itemGroupElement = document.createElement('div');
  itemGroupElement.classList.add('item-group');

  // Add the avatar image
  const avatarImage = document.createElement('img');
  avatarImage.src = avatarUrl;
  avatarImage.alt = 'Your Avatar';
  itemGroupElement.appendChild(avatarImage);

  // Add the option text
  const optionText = document.createElement('p');
  optionText.textContent = newOption;
  itemGroupElement.appendChild(optionText);

  // Append the item-group element to the item-group container
  document.getElementById('item-group').appendChild(itemGroupElement);
}
```

