    {
        var rang1 = new Range { StartIncl = 1, EndExl = 5 };
        var rang2 = new Range { StartIncl = 3, EndExl = 7 };

        var overlap = FindOverlap(rang1, rang2);

        Console.WriteLine("Overlap: " + overlap);
    }

    public static List<Range> FindOverlap(Range rang1, Range rang2)
    {
        int start = Math.Max(rang1.StartIncl, rang2.StartIncl);
        int end = Math.Min(rang1.EndExl, rang2.EndExl);

        List<Range> overlaps = new List<Range>();

        for (int i = start; i <= end; i++)
        {
            if (i >= rang1.StartIncl && i <= rang1.EndExl && i >= rang2.StartIncl && i <= rang2.EndExl)
            {
                overlaps.Add(new Range { StartIncl = i, EndExl = i });
            }
        }

        return overlaps;
    }
}

public class Range
{
    public int StartIncl { get; set; }
    public int EndExl { get; set; }
}
